# Simple backtracking with MRV heuristic and forward checking
import sys
sys.setrecursionlimit(10000)

colors = [-1]*n
domains = [set(range(4)) for _ in range(n)]

def backtrack():
    # Find uncolored vertex with smallest domain (MRV)
    min_domain_size = 5
    var = -1
    for v in range(n):
        if colors[v] == -1:
            ds = len(domains[v])
            if ds == 0:
                return False
            if ds < min_domain_size:
                min_domain_size = ds
                var = v
                if ds == 1:
                    break
    if var == -1:
        return True  # all colored

    # Try values in domain
