        # Check if assignment is consistent
        consistent = True
        for nb in adj[var]:
            if colors[nb] == c:
                consistent = False
                break
        if not consistent:
            continue

        # Assign and propagate
        colors[var] = c
        # Save domain for neighbors for backtracking
        saved = {}
        for nb in adj[var]:
            if colors[nb] == -1 and c in domains[nb]:
                saved[nb] = set(domains[nb])
                domains[nb].discard(c)
